import logging
from time import sleep

from serial import Serial
from serial.serialutil import SerialException

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.devices.base import PDU


class TdkLambda(Serial, PDU):
    def __init__(self, host, timeout=30, write_timeout=30):
        serial_port = host
        try:
            super(TdkLambda, self).__init__(
                port=serial_port, timeout=timeout, write_timeout=write_timeout
            )
        except SerialException:  # it was reported, that reconnection may be needed
            sleep(2)
            super(TdkLambda, self).__init__(
                port=serial_port, timeout=timeout, write_timeout=write_timeout
            )
        self.close()

    def set_voltage(self, port, voltage):
        """TDK Lambda has only 1 port, therefore port variable is not used."""
        self.open()
        self._write(f"GPV {voltage}")
        self.close()

    def reset(self, ports, time_interval=5):
        self._set_port_status(ports, DeviceStatus.OFF)
        sleep(time_interval)
        self._set_port_status(ports, DeviceStatus.ON)

    def _set_port_status(self, port, status):
        """TDK Lambda has only 1 port, therefore port variable is not used."""
        status = 0 if status == "off" else 1
        self.open()
        self._write(f"GOUT {status}")
        self.close()

    def _write(self, command):
        super(TdkLambda, self).write(command.encode() + b"\r\n")

    def get_port_status(self, port):
        logging.critical(
            "Currently it is unknown if tdk lambda supports getting port status.\n"
            "If functionality is needed and actually supported- "
            "please contact taf.hw.pdu maintainers."
        )
        raise NotImplementedError(
            "Getting port status not implemented. Check logs for more info."
        )

    def _port_setting(self):
        """Not implemented due to not supported get_port_status"""
